const listPageSize=10;
function usePaginatedRows(rows,pageSize=listPageSize) {
  const [page,setPage]=useState(1),totalPages=Math.max(1,Math.ceil(rows.length/pageSize)),identity=rows.map((row,index)=>row?.id??row?.databaseId??index).join("|");
  useEffect(()=>setPage(1),[identity]);
  useEffect(()=>{if(page>totalPages)setPage(totalPages)},[page,totalPages]);
  return {page,totalPages,totalItems:rows.length,rows:rows.slice((page-1)*pageSize,page*pageSize),setPage};
}
function Pagination({page,totalPages,totalItems,onPageChange}) {
  const {t}=useI18n();
  if(totalItems<=listPageSize)return null;
  const start=Math.max(1,Math.min(page-2,totalPages-4)),end=Math.min(totalPages,start+4),pages=[];for(let number=start;number<=end;number++)pages.push(number);
  return <nav className="pagination" aria-label={t("pagination")}><span>{t("paginationSummary").replace("{page}",page).replace("{pages}",totalPages).replace("{count}",totalItems)}</span><div><button type="button" className="outline" disabled={page<=1} onClick={()=>onPageChange(page-1)}>{t("previousPage")}</button>{pages.map(number=><button type="button" key={number} className={number===page?"page-number active":"page-number"} aria-current={number===page?"page":undefined} onClick={()=>onPageChange(number)}>{number}</button>)}<button type="button" className="outline" disabled={page>=totalPages} onClick={()=>onPageChange(page+1)}>{t("nextPage")}</button></div></nav>;
}
function DeleteRowButton({onDelete,label="",confirmText=""}) {
  const {t}=useI18n();
  const [deleting,setDeleting]=useState(false);
  const remove=async()=>{if(!window.confirm(`${confirmText||t("confirmDeleteRecord")}${label?`\n${label}`:""}`))return;setDeleting(true);try{await onDelete()}catch(error){window.alert(`${t("deleteFailed")}：${error.message}`)}finally{setDeleting(false)}};
  return <button type="button" className="danger" title={t("deleteRecord")} aria-label={`${t("deleteRecord")} ${label}`} disabled={deleting} onClick={remove}><Trash2 size={16}/></button>;
}
function DataTable({ columns, rows, renderCell, onEdit, onDetail, onPrint, onDelete, selectedRowIds, onSelectionChange, selectionKey=row=>row.id, className="" }) {
  const {t}=useI18n(),pagination=usePaginatedRows(rows),selectable=selectedRowIds instanceof Set&&Boolean(onSelectionChange),pageIds=pagination.rows.map(row=>String(selectionKey(row))),allPageSelected=selectable&&pageIds.length>0&&pageIds.every(id=>selectedRowIds.has(id));
  const toggleRow=(id,checked)=>{const next=new Set(selectedRowIds);if(checked)next.add(id);else next.delete(id);onSelectionChange(next)};
  const togglePage=checked=>{const next=new Set(selectedRowIds);pageIds.forEach(id=>checked?next.add(id):next.delete(id));onSelectionChange(next)};
  return <div className={`table-wrap ${className}`}><table><thead><tr><th><input type="checkbox" aria-label={t("selectCurrentPage")} disabled={!selectable||!pageIds.length} checked={allPageSelected} onChange={event=>togglePage(event.target.checked)}/></th>{columns.map(c=><th key={c.key} style={c.width?{width:c.width,minWidth:c.width,maxWidth:c.width}:undefined}>{c.label}</th>)}<th>{t("actions")}</th></tr></thead><tbody>{pagination.rows.map(row=>{const rowId=String(selectionKey(row));return <tr key={row.id}><td><input type="checkbox" aria-label={`${t("selectRow")} ${row.id||row.name||""}`} disabled={!selectable} checked={selectable&&selectedRowIds.has(rowId)} onChange={event=>toggleRow(rowId,event.target.checked)}/></td>{columns.map(c=><td key={c.key} style={c.width?{width:c.width,minWidth:c.width,maxWidth:c.width}:undefined}>{renderCell?renderCell(row,c):row[c.key]}</td>)}<td><div className="row-actions">{onEdit&&<button title={t("edit")} onClick={()=>onEdit(row)}><Pencil size={16}/></button>}{onDetail&&<button title={t("details")} onClick={()=>onDetail(row)}><ClipboardList size={16}/></button>}{onPrint&&<button title={t("printDeliveryNote")} onClick={()=>onPrint(row)}><Printer size={16}/></button>}{onDelete&&<DeleteRowButton onDelete={()=>onDelete(row)} label={row.id||row.name||""}/>}</div></td></tr>})}</tbody></table>{!rows.length&&<div className="empty">{t("noData")}</div>}<Pagination {...pagination} onPageChange={pagination.setPage}/></div>;
}
function CompactTable({rows,columns}) { return <div className="compact-table">{rows.map(r=><div key={r.id}>{columns.map(c=><span key={c}>{c==="total"?money(r[c],r.currency):r[c]}</span>)}</div>)}</div>; }

function ProductImageCell({product,onUpload,canUpload}) {
  const {t}=useI18n();
  const [uploading,setUploading]=useState(false);
  const inputRef=useRef(null);
  const upload=async event=>{const file=event.target.files?.[0];event.target.value="";if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>5*1024*1024)return onUpload(product,null,t("invalidProductImage"));setUploading(true);try{await onUpload(product,file)}finally{setUploading(false)}};
  if(!canUpload)return product.imageUrl?<img className="product-thumbnail" src={product.imageUrl} alt={product.name} loading="lazy"/>:<span className="product-image-placeholder"><Plus size={18}/></span>;
  const actionLabel=`${t(product.imageUrl?"replaceProductImage":"uploadProductImage")}：${product.name}`;
  return <span className="product-image-picker"><button type="button" className={`product-image-button ${product.imageUrl?"has-image":""}`} aria-label={actionLabel} disabled={uploading} title={actionLabel} onClick={()=>inputRef.current?.click()}>{product.imageUrl?<img src={product.imageUrl} alt="" loading="lazy"/>:<Plus size={20}/>} {uploading&&<span className="product-image-loading"/>}</button><input ref={inputRef} type="file" accept="image/jpeg,image/png,image/webp" disabled={uploading} onChange={upload}/></span>;
}

