function SalesColumnSelector({options,selected,onToggle,onReset}) {
  const {t}=useI18n();
  const [open,setOpen]=useState(false);
  const selectorRef=useRef(null);
  useEffect(()=>{
    if(!open)return undefined;
    const close=event=>{if(!selectorRef.current?.contains(event.target))setOpen(false)};
    document.addEventListener("pointerdown",close);
    return()=>document.removeEventListener("pointerdown",close);
  },[open]);
  return <div ref={selectorRef} className={`column-selector controlled-column-selector ${open?"open":""}`}><button type="button" className="outline column-selector-trigger" aria-haspopup="true" aria-expanded={open} onClick={()=>setOpen(current=>!current)}><Columns3 size={16}/>{t("selectColumns")}</button>{open&&<div className="column-selector-menu"><div className="column-selector-title">{t("salesListColumns")}</div>{options.map(option=><label key={option.key}><input type="checkbox" checked={selected.includes(option.key)} onChange={()=>onToggle(option.key)}/><span>{option.label}</span></label>)}<button type="button" className="outline" onClick={onReset}>{t("resetColumns")}</button></div>}</div>;
}

